<?php defined( 'ABSPATH' ) || exit; $members = aspirecre_team_members(); ?>
	<?php if ( $members ) : ?><div class="team-grid"><?php foreach ( $members as $member ) : ?>
	<article class="team-card"><a class="card-link" href="<?php echo esc_url( get_permalink( $member->ID ) ); ?>" aria-labelledby="member-title-<?php echo esc_attr( $member->ID ); ?>"><div class="person-image"><?php if ( has_post_thumbnail( $member->ID ) ) : echo get_the_post_thumbnail( $member->ID, 'aspire-person', array( 'alt' => '', 'loading' => 'lazy', 'sizes' => '(max-width: 560px) 100vw, (max-width: 1000px) 50vw, 25vw' ) ); else : ?><span class="card-placeholder">Portrait to come</span><?php endif; ?></div><div class="person-copy"><div><h3 id="member-title-<?php echo esc_attr( $member->ID ); ?>"><?php echo esc_html( get_the_title( $member->ID ) ); ?></h3><p><?php echo esc_html( get_post_meta( $member->ID, '_aspire_job_title', true ) ); ?></p></div><span class="card-arrow" aria-hidden="true">↗</span></div></a></article>
	<?php endforeach; ?></div><?php else : ?><div class="empty-state"><p>Team profiles will appear here when available.</p><?php if ( current_user_can( 'edit_posts' ) ) : ?><a href="<?php echo esc_url( admin_url( 'edit.php?post_type=team_member' ) ); ?>">Manage team members <span aria-hidden="true">→</span></a><?php endif; ?></div><?php endif; ?>
